import React, { useState, useMemo } from 'react';
import { WordClass, Level, WordData } from '../types';
import { analyzeTextWithAI } from '../services/geminiService';
import { saveLevelLocally } from '../services/supabaseService';

interface Props {
  onSave: (level: Level) => void;
  onClose: () => void;
}

const CATEGORY_COLORS: Record<string, string> = {
  [WordClass.SUSTANTIVO]: 'bg-blue-500',
  [WordClass.ADJETIVO]: 'bg-yellow-500',
  [WordClass.VERBO]: 'bg-red-500',
  [WordClass.ADVERBIO]: 'bg-purple-500',
  [WordClass.PRONOMBRE]: 'bg-pink-500',
  [WordClass.PREPOSICION]: 'bg-green-500',
  [WordClass.CONJUNCION]: 'bg-orange-500',
  [WordClass.DETERMINANTE]: 'bg-cyan-500',
};

const MAX_WORDS = 50;

export const Editor: React.FC<Props> = ({ onSave, onClose }) => {
  const [step, setStep] = useState<'INPUT' | 'TAGGING'>('INPUT');
  const [text, setText] = useState('');
  const [title, setTitle] = useState('');
  const [tokens, setTokens] = useState<WordData[]>([]);
  const [activeCategory, setActiveCategory] = useState<WordClass | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [copied, setCopied] = useState(false);

  const isMidnight = document.body.classList.contains('konami-active');

  const wordCount = useMemo(() => {
    return text.trim() ? text.trim().split(/\s+/).length : 0;
  }, [text]);

  const isTooLong = wordCount > MAX_WORDS;

  const prepareTagging = () => {
    if (!text.trim() || isTooLong) return;
    // Dividimos por espacios pero mantenemos la puntuación pegada a la palabra
    const words = text.trim().split(/\s+/).map((w, i) => ({
      text: w,
      category: null as any,
      id: `manual-${i}-${Date.now()}`
    }));
    setTokens(words);
    setStep('TAGGING');
  };

  const handleAISuggestion = async () => {
    if (!text.trim() || isTooLong) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeTextWithAI(text);
      if (result && result.length > 0) {
        // La IA a veces limpia la puntuación. Vamos a intentar re-mapear
        // basándonos en el texto original por posición.
        const originalWords = text.trim().split(/\s+/);
        const mappedTokens = originalWords.map((orig, i) => {
          // Buscamos la sugerencia de la IA para esta posición
          const suggestion = result[i];
          return {
            text: orig, // Mantenemos el original con puntuación
            category: suggestion ? suggestion.category as WordClass : null as any,
            id: `ai-${i}-${Date.now()}`
          };
        });
        setTokens(mappedTokens);
        setStep('TAGGING');
      } else {
        prepareTagging();
      }
    } catch (e: any) {
      prepareTagging();
    } finally {
      setIsAnalyzing(false);
    }
  };

  const toggleWordCategory = (tokenId: string) => {
    if (!activeCategory) return;
    setTokens(prev => prev.map(t => 
      t.id === tokenId 
        ? { ...t, category: t.category === activeCategory ? null as any : activeCategory } 
        : t
    ));
  };

  const handleSave = (shouldExport: boolean = false) => {
    const taggedTokens = tokens.filter(t => t.category !== null);
    if (taggedTokens.length === 0) {
      alert("Etiqueta al menos una palabra seleccionando una categoría arriba y pulsando en las palabras del texto.");
      return;
    }

    const newLevel: Level = {
      id: Date.now(),
      title: title || "Texto de Usuario",
      text: tokens.map(t => t.text).join(' '),
      words: tokens,
      timeLimit: 30,
      targetCategory: taggedTokens[0].category,
      categoryGroup: 'Tus Niveles'
    };

    if (shouldExport) {
      const code = JSON.stringify(newLevel, null, 2);
      navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
      return;
    }

    saveLevelLocally(newLevel);
    onSave(newLevel);
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-indigo-950/90 backdrop-blur-xl p-2 md:p-4 animate-in fade-in duration-300">
      <div className={`w-full max-w-6xl rounded-[2.5rem] md:rounded-[3rem] overflow-hidden flex flex-col h-[95vh] md:h-[90vh] shadow-2xl border-4 md:border-8 ${isMidnight ? 'bg-slate-900 border-slate-700' : 'bg-white border-indigo-400'}`}>

        <div className={`p-4 md:p-6 flex justify-between items-center text-white ${isMidnight ? 'bg-indigo-900' : 'bg-indigo-600'}`}>
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 md:w-12 md:h-12 bg-white/20 rounded-2xl flex items-center justify-center text-xl md:text-2xl"><i className="fas fa-pen-nib"></i></div>
            <div>
              <h2 className="text-lg md:text-xl font-black italic uppercase leading-tight">CREADOR DE NIVELES</h2>
              <p className="text-[10px] font-bold opacity-70 uppercase tracking-wider">La puntuación se conservará automáticamente</p>
            </div>
          </div>
          <button onClick={onClose} className="hover:bg-black/20 w-10 h-10 rounded-full transition-colors flex items-center justify-center"><i className="fas fa-times"></i></button>
        </div>

        <div className="flex-1 overflow-hidden flex flex-col p-4 md:p-6 space-y-4">
          {step === 'INPUT' ? (
            <div className="flex flex-col h-full space-y-4 animate-in slide-in-from-left duration-500">
              <input value={title} onChange={e => setTitle(e.target.value)} className={`w-full p-3 rounded-xl border-2 outline-none font-bold ${isMidnight ? 'bg-slate-800 border-slate-700 text-white' : 'bg-indigo-50 border-indigo-100'}`} placeholder="Título del texto (ej: El Quijote)..." />
              <textarea value={text} onChange={e => setText(e.target.value)} className={`flex-1 w-full p-4 rounded-2xl border-2 outline-none font-medium leading-relaxed resize-none text-lg ${isMidnight ? 'bg-slate-800 border-slate-700 text-white' : 'bg-indigo-50 border-indigo-100'} ${isTooLong ? 'border-rose-400' : ''}`} placeholder="Escribe o pega tu texto aquí. Los puntos, comas y signos se mantendrán..." />
              <div className="flex justify-between items-center text-xs font-bold px-2">
                <span className={isTooLong ? 'text-rose-500' : 'text-slate-400 uppercase'}>{wordCount}/{MAX_WORDS} palabras</span>
                {isTooLong && <span className="text-rose-500 animate-pulse">¡Texto demasiado largo!</span>}
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <button onClick={handleAISuggestion} disabled={isAnalyzing || !text.trim() || isTooLong} className="py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-black disabled:opacity-50 shadow-lg transition-all active:scale-95 flex items-center justify-center">
                  {isAnalyzing ? <i className="fas fa-spinner fa-spin mr-2"></i> : <i className="fas fa-magic mr-2"></i>}
                  ANÁLISIS INTELIGENTE
                </button>
                <button onClick={prepareTagging} disabled={!text.trim() || isTooLong} className="py-4 bg-slate-200 text-slate-700 rounded-xl font-black hover:bg-slate-300 transition-colors shadow-sm active:scale-95">REVISIÓN MANUAL</button>
              </div>
            </div>
          ) : (
            <div className="flex flex-col h-full space-y-4 animate-in slide-in-from-right duration-500 overflow-hidden">
              <div className="flex flex-wrap gap-2 justify-center p-3 bg-slate-100 dark:bg-slate-800/50 rounded-2xl border-2 border-indigo-50">
                {Object.values(WordClass).map(cat => (
                  <button key={cat} onClick={() => setActiveCategory(cat)} className={`px-3 py-2 rounded-xl text-[10px] md:text-xs font-black uppercase transition-all shadow-sm ${activeCategory === cat ? `${CATEGORY_COLORS[cat]} text-white scale-110 ring-4 ring-indigo-200` : 'bg-white text-slate-500 hover:bg-indigo-50'}`}>
                    {cat}
                  </button>
                ))}
              </div>
              <div className={`flex-1 overflow-y-auto p-6 md:p-8 rounded-[2.5rem] border-2 shadow-inner ${isMidnight ? 'bg-slate-800 border-slate-700' : 'bg-indigo-50 border-indigo-100'}`}>
                <div className="flex flex-wrap gap-x-2 md:gap-x-3 gap-y-4 justify-center">
                  {tokens.map((token) => (
                    <span key={token.id} onClick={() => toggleWordCategory(token.id)} className={`cursor-pointer px-3 py-1.5 rounded-xl text-xl md:text-2xl font-black transition-all transform hover:scale-110 active:scale-90 ${token.category ? `${CATEGORY_COLORS[token.category]} text-white shadow-md` : isMidnight ? 'text-white' : 'text-slate-700 hover:bg-indigo-200'}`}>
                      {token.text}
                    </span>
                  ))}
                </div>
              </div>
              <div className="flex flex-col md:flex-row justify-between items-center gap-4 pt-2 border-t border-slate-100">
                <button onClick={() => setStep('INPUT')} className="text-indigo-500 text-sm font-black hover:underline uppercase tracking-tight"><i className="fas fa-arrow-left mr-2"></i> EDITAR TEXTO</button>
                <div className="flex gap-3 w-full md:w-auto">
                  <button onClick={() => handleSave(true)} className={`flex-1 md:flex-none px-6 py-3 rounded-xl font-black text-xs transition-all shadow-md active:scale-95 ${copied ? 'bg-green-500 text-white' : 'bg-slate-200 text-slate-600 hover:bg-slate-300'}`}>
                    <i className={`fas ${copied ? 'fa-check' : 'fa-code'} mr-2`}></i>
                    {copied ? '¡COPIADO!' : 'CÓDIGO'}
                  </button>
                  <button onClick={() => handleSave(false)} className="flex-1 md:flex-none px-8 py-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-black text-xs shadow-lg shadow-indigo-200 active:scale-95 transition-all">
                    GUARDAR Y JUGAR
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { GameView, GameState, WordClass, Level, WordData, Achievement, LevelGroup } from './types';
import { INITIAL_LEVELS, LITERARY_ES_LEVELS, LITERARY_UNIVERSAL_LEVELS, KONAMI_CODE, INITIAL_ACHIEVEMENTS } from './constants';
import { GameHUD } from './components/GameHUD';
import { Editor } from './components/Editor';
import { AchievementsModal } from './components/AchievementsModal';
import { Leaderboard } from './components/Leaderboard';
import { fetchCommunityLevels, saveScore } from './services/supabaseService';

export const getPluralCategory = (cat: WordClass): string => {
  switch (cat) {
    case WordClass.PREPOSICION: return 'Preposiciones';
    case WordClass.CONJUNCION: return 'Conjunciones';
    default: return `${cat}s`;
  }
};

interface Reward {
  type: 'hint' | 'cleaner' | 'shield' | 'life';
  label: string;
  icon: string;
  color: string;
}

const TutorialSign: React.FC<{ 
  text: string; 
  onNext: () => void; 
  position: 'category' | 'time' | 'lives' | 'items' | 'words';
  isMidnight: boolean;
}> = ({ text, onNext, position, isMidnight }) => {
  const positionClasses = {
    category: 'top-28 md:top-36 left-1/2 -translate-x-1/2',
    time: 'top-28 md:top-36 right-2 md:right-10',
    lives: 'top-28 md:top-36 left-2 md:left-10',
    items: 'bottom-32 md:bottom-48 left-1/2 -translate-x-1/2',
    words: 'top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2'
  };

  const arrowClasses = {
    category: 'top-full left-1/2 -translate-x-1/2 border-t-[20px]',
    time: 'top-full right-10 border-t-[20px]',
    lives: 'top-full left-10 border-t-[20px]',
    items: 'bottom-full left-1/2 -translate-x-1/2 border-b-[20px]',
    words: 'hidden'
  };

  const arrowThemeClass = isMidnight ? (position === 'items' ? 'border-b-slate-800' : 'border-t-slate-800') : (position === 'items' ? 'border-b-white' : 'border-t-white');

  return (
    <div 
      className={`fixed ${positionClasses[position]} z-[150] w-[90%] max-w-sm animate-in zoom-in duration-300 cursor-pointer`}
      onClick={onNext}
    >
      <div className={`relative p-6 rounded-[2rem] border-4 shadow-2xl ${isMidnight ? 'bg-slate-800 border-indigo-500 text-white' : 'bg-white border-yellow-400 text-indigo-900'}`}>
        <div className={`absolute w-0 h-0 border-l-[15px] border-l-transparent border-r-[15px] border-r-transparent ${arrowClasses[position]} ${arrowThemeClass}`}></div>
        <p className="text-lg font-black leading-tight mb-4 text-center">{text}</p>
        <div className="flex justify-center">
          <span className="px-4 py-1 bg-indigo-600 text-white text-[10px] font-black rounded-full uppercase tracking-widest animate-pulse">Siguiente <i className="fas fa-chevron-right ml-1"></i></span>
        </div>
      </div>
