                ))}
              </div>
            </div>

            {/* Título de la obra debajo del texto */}
            <p className={`mt-6 text-[10px] md:text-sm font-black uppercase tracking-[0.2em] italic opacity-50 ${showKonamiEffect ? 'text-indigo-300' : 'text-indigo-900'}`}>
